commands.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {isDeepStrictEqual} from 'node:util';
import {execFileSync} from 'node:child_process';
import {parseFeatureRows} from './scripts/internal/feature_implementation_manifest_lib.mjs';
import {applyApprovedReview4SemanticClosure} from './scripts/internal/feature_semantic_review4_apply.mjs';
const rootDir=process.cwd(), file='test/fixtures/project_feature_implementation_evidence.json', inv='docs/project-feature-test-inventory.md';
const read=f=>JSON.parse(fs.readFileSync(f,'utf8'));
const inventoryText=fs.readFileSync(inv,'utf8'),rows=parseFeatureRows(inventoryText);
assert.equal(rows.length,986);assert(isDeepStrictEqual(rows,parseFeatureRows(execFileSync('git',['show','HEAD:'+inv],{encoding:'utf8'}))));
const raw=fs.readFileSync(file,'utf8'),manifest=JSON.parse(raw);
const next=applyApprovedReview4SemanticClosure({rootDir,inventoryText,rows,manifest,audit:read('test/fixtures/v390_review4_feature_semantic_source_audit.json'),approvals:read('test/fixtures/v390_review4_feature_semantic_source_approvals.json')});
const changed=Object.keys({...manifest,...next}).filter(key=>!isDeepStrictEqual(manifest[key],next[key]));
assert.deepEqual(changed,['inventorySha256']);
const formatted=JSON.stringify(next,null,2)+'\n';
assert.equal(formatted,raw.replace('"inventorySha256": "'+manifest.inventorySha256+'"','"inventorySha256": "'+next.inventorySha256+'"'));
fs.writeFileSync(file,formatted);
assert(isDeepStrictEqual(read(file),next));
console.log(JSON.stringify({rows:986,onlyChangedField:'inventorySha256',approvalAndProofUnchanged:true,previous:manifest.inventorySha256,current:next.inventorySha256}));
NODE
